/** PoolKey struct type for viem writes. */
export function poolKey(d: CadenceDeployment) {
  return {
    currency0: "0x0000000000000000000000000000000000000000" as const,
    currency1: d.usdc,
    fee: 0,
    tickSpacing: 60,
    hooks: d.hook,
  };
}

export type CadenceAbis = typeof slotsAbi | typeof hookAbi | typeof routerAbi | typeof usdcAbi;
export type AbiLike = Abi;
